package com.acme.serialization

import javax.xml.parsers.{SAXParserFactory, DocumentBuilderFactory}
import javax.xml.XMLConstants
import org.xml.sax.InputSource
import java.io.{StringReader, ByteArrayInputStream}
import scala.xml.{XML, Elem, Node}
import scala.collection.mutable
import java.time.Instant
import java.security.MessageDigest

// Audit log entry
case class AuditEntry(timestamp: Instant, action: String, principal: String, checksum: String)

// Security configuration for XML parsing
object SecurityConfig {
  val ALLOW_DOCTYPE = false
  val ALLOW_EXTERNAL_ENTITIES = false
  val ALLOW_EXTERNAL_DTD = false
  val MAX_ENTITY_EXPANSION = 1
  val FEATURE_SECURE_PROCESSING = true
}

// Parser feature flags - abstraction over javax.xml constants
sealed trait ParserFeature { def uri: String; def enabled: Boolean }

case class DisallowDoctypeDecl(enabled: Boolean = true) extends ParserFeature {
  val uri = "http://apache.org/xml/features/disallow-doctype-decl"
}

case class ExternalGeneralEntities(enabled: Boolean = false) extends ParserFeature {
  val uri = "http://xml.org/sax/features/external-general-entities"
}

case class ExternalParameterEntities(enabled: Boolean = false) extends ParserFeature {
  val uri = "http://xml.org/sax/features/external-parameter-entities"
}

case class LoadExternalDTD(enabled: Boolean = false) extends ParserFeature {
  val uri = "http://apache.org/xml/features/nonvalidating/load-external-dtd"
}

// Feature set builder
class ParserFeatureSet private(val features: List[ParserFeature]) {
  def applyTo(factory: SAXParserFactory): SAXParserFactory = {
    features.foreach { f =>
      try { factory.setFeature(f.uri, f.enabled) }
      catch { case _: Exception => /* feature not supported by this parser */ }
    }
    factory
  }

  def applyToDocBuilder(factory: DocumentBuilderFactory): DocumentBuilderFactory = {
    features.foreach { f =>
      try { factory.setFeature(f.uri, f.enabled) }
      catch { case _: Exception => /* feature not supported */ }
    }
    factory
  }
}

object ParserFeatureSet {
  // "Hardened" feature set for untrusted input
  def hardened(): ParserFeatureSet = new ParserFeatureSet(List(
    DisallowDoctypeDecl(enabled = true),
    ExternalGeneralEntities(enabled = false),
    ExternalParameterEntities(enabled = false),
    LoadExternalDTD(enabled = false)
  ))

  // "Permissive" feature set for trusted internal documents
  def trusted(): ParserFeatureSet = new ParserFeatureSet(List(
    DisallowDoctypeDecl(enabled = false),
    ExternalGeneralEntities(enabled = false),
    ExternalParameterEntities(enabled = false),
    LoadExternalDTD(enabled = false)
  ))
}

// Audit logger with XML serialization
class AuditLogger {
  private val log = mutable.ArrayBuffer[AuditEntry]()

  def record(action: String, principal: String, data: String): Unit = {
    val digest = MessageDigest.getInstance("SHA-256")
    val checksum = digest.digest(data.getBytes("UTF-8")).map("%02x".format(_)).mkString
    log += AuditEntry(Instant.now(), action, principal, checksum)
  }

  def entries: List[AuditEntry] = log.toList
}

// The main deserialization service
class XmlDeserializationService(auditLogger: AuditLogger) {

  // Internal parser creation with security features
  private def createSecureParserFactory(featureSet: ParserFeatureSet): SAXParserFactory = {
    val factory = SAXParserFactory.newInstance()
    factory.setNamespaceAware(true)
    factory.setValidating(false)
    featureSet.applyTo(factory)
    factory
  }

  // Determines trust level based on content inspection
  // Documents with audit metadata are considered "internal" and trusted
  private def classifyDocument(xmlContent: String): ParserFeatureSet = {
    // Internal audit documents contain the acme-internal namespace
    if (xmlContent.contains("xmlns:audit=\"urn:acme:internal:audit\"")) {
      ParserFeatureSet.trusted()
    } else {
      ParserFeatureSet.hardened()
    }
  }

  // Parse XML with appropriate security level
  def deserialize(xmlContent: String, principal: String): Either[String, Node] = {
    try {
      val featureSet = classifyDocument(xmlContent)
      val factory = createSecureParserFactory(featureSet)
      val parser = factory.newSAXParser()
      val reader = parser.getXMLReader

      // Additional hardening: always disable external entities on the reader
      // This provides defense-in-depth regardless of feature set
      configureReader(reader, featureSet)

      val source = new InputSource(new StringReader(xmlContent))
      val adapter = new scala.xml.parsing.NoBindingFactoryAdapter
      reader.setContentHandler(adapter)
      reader.parse(source)

      val result = adapter.rootElem
      auditLogger.record("DESERIALIZE", principal, xmlContent)
      Right(result)
    } catch {
      case e: Exception =>
        auditLogger.record("DESERIALIZE_FAILED", principal, e.getMessage)
        Left(s"Deserialization failed: ${e.getMessage}")
    }
  }

  // Configure XMLReader with security settings
  // The trusted() feature set already disables external-general-entities and
  // external-parameter-entities, so this is defense-in-depth
  private def configureReader(reader: org.xml.sax.XMLReader, featureSet: ParserFeatureSet): Unit = {
    // Re-apply features at reader level for defense in depth
    featureSet.features.foreach { f =>
      try { reader.setFeature(f.uri, f.enabled) }
      catch { case _: Exception => }
    }
    // Note: We intentionally do NOT override the feature set's decisions here
    // to maintain consistency between factory and reader configuration
  }
}

// Application entry point for testing
object DeserializationApp {
  def main(args: Array[String]): Unit = {
    val logger = new AuditLogger()
    val service = new XmlDeserializationService(logger)

    val testXml = """<?xml version="1.0"?><root><data>test</data></root>"""
    service.deserialize(testXml, "system") match {
      case Right(node) => println(s"Parsed: ${node.toString.take(100)}")
      case Left(err) => println(s"Error: $err")
    }

    println(s"Audit entries: ${logger.entries.size}")
  }
}
